            if x.startswith(' ') and x.endswith(' ') and x.strip(): x=x[1:-1]
            return hold('<code>'+esc_text(x)+'</code>')
        text=re.sub(r'(`+)([\s\S]*?)\1',code,text)
        def raw(m):
