            return a+'>'+self.inline(label)+'</a>'
        text=re.sub(r'!\[([^\]]*)\]\((?:<([^>]+)>|(\S+?))(?:\s+(?:"([^"]*)"|\'([^\']*)\'|\(([^)]*)\)))?\)',lambda m:image(type('M',(),{'group':lambda _,n: [None,m.group(1),m.group(2) or m.group(3),m.group(4) or m.group(5) or m.group(6)][n]})()),text)
