        def replace_ref(m):
            key=(m.group(3) or m.group(2)).strip().casefold()
            if key not in self.refs: return m.group(0)
            url,title=self.refs[key]
            if m.group(1):
                return '<img src="'+html.escape(url,quote=True)+'" alt="'+html.escape(m.group(2),quote=True)+'"'+((' title="'+html.escape(title,quote=True)+'"') if title else '')+' />'
            return '<a href="'+html.escape(url,quote=True)+'"'+((' title="'+html.escape(title,quote=True)+'"') if title else '')+'>'+self.inline(m.group(2))+'</a>'
